//! 🚪️ Worker admission retains the genuine source and every partial birth before posting.
use super::*;
use semio_framework_value::RetainedWorkOutcome;

/// 🧳️ The actual caller owns its pending worker until receiver publication and paid retirement.
pub struct OriginalWorkerJobAdmission<J>{prepared:OriginalWorkerPageReservation,storage:Vec<NativeWorkerAuthorityState<J>>,authority:Option<OriginalWorkerJobAuthority<J>>,binding:Option<OriginalSourceBinding>,closing:bool}
impl<J> OriginalWorkerJobAdmission<J>{
 pub const fn new()->Self{Self{prepared:OriginalWorkerPageReservation::new(),storage:Vec::new(),authority:None,binding:None,closing:false}}
 pub fn ready(&self)->bool{!self.closing&&self.authority.as_ref().is_some_and(|owner|owner.original.job.present&&owner.original.params.is_some())}
 pub fn job(&self)->Option<&J>{self.authority.as_ref().and_then(|owner|owner.original.job.original())}
 pub fn terminal_is_empty(&self)->bool{self.authority.is_none()&&self.storage.capacity()==0&&self.prepared.terminal_is_empty()&&self.binding.is_none()&&!self.closing}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.original_source_parent()?.validate_borrowed_context(cx)?;if self.binding.is_some_and(|binding|!binding.matches(cx)){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"worker admission requires its genuine original caller source").into())}Ok(())}
 fn enter(cx:&StepContext<'_>,capacity:usize,release:usize,closing:bool)->bool{let grant=cx.retained_grant();!(if closing{cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()})&&grant.maximum_items>0&&grant.maximum_depth>0&&grant.maximum_capacity_bytes>=capacity&&grant.maximum_release_bytes>=release}
 fn metadata(cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{receive_original_retained_work(cx,RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()})),work:1})?;Ok(())}
 pub fn advance(&mut self,job:&mut Option<J>,params:&mut Option<BatchJobParams>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.closing{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"worker admission cannot advance after paid close begins").into())}if self.ready(){return Ok(true)}if !Self::enter(cx,0,0,false){return Ok(false)}
  if self.binding.is_none(){let original=params.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"worker admission requires its retained original parameters"))?;if job.is_none()||(original.operation,original.generation)!=(cx.operation(),cx.generation())||!original.cancel.is_same_node(cx.original_cancel_token())||!std::ptr::fn_addr_eq(original.now_us,cx.clock_source()){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"worker admission input differs from its actual source").into())}self.binding=Some(OriginalSourceBinding::borrow(cx));Self::metadata(cx)?;return Ok(false)}
  if self.authority.is_none()&&!self.prepared.ready(){self.prepared.admit_step(cx)?;return Ok(false)}
  if self.authority.is_none()&&self.storage.capacity()==0{let bytes=size_of::<NativeWorkerAuthorityState<J>>();if !Self::enter(cx,bytes,0,false){return Ok(false)}let result=match self.storage.try_reserve_exact(1){Ok(())=>Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:self.storage.capacity()*bytes,..Default::default()})),Err(_)=>Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"worker authority native allocation refused"))};receive_original_retained_work(cx,RetainedWorkOutcome{result,work:1})?;return Ok(false)}
  if self.authority.is_none(){let binding=self.binding.ok_or_else(||ValueError::invariant("binding absent"))?;let prepared=std::mem::replace(&mut self.prepared,OriginalWorkerPageReservation::new());let original=NativeWorkerAuthorityOwner::write_pending_storage(std::mem::take(&mut self.storage),binding.operation(),binding.generation(),prepared);self.authority=Some(OriginalWorkerJobAuthority{original});Self::metadata(cx)?;return Ok(false)}
  let owner=self.authority.as_mut().ok_or_else(||ValueError::invariant("authority absent"))?;let original=params.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"worker source handoff lost its original parameters"))?;if job.is_none()||(original.operation,original.generation)!=(cx.operation(),cx.generation())||!original.cancel.is_same_node(cx.original_cancel_token()){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"worker source handoff changed its original input").into())}unsafe{owner.original.write_owned_source_prepaid(job,params);}Self::metadata(cx)?;Ok(true)
 }
 pub fn take_ready(&mut self,output:&mut Option<OriginalWorkerJobAuthority<J>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if output.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"worker receiver slot already owns an authority").into())}if !self.ready()||!Self::enter(cx,0,0,false){return Ok(false)}*output=self.authority.take();Self::metadata(cx)?;Ok(true)}
}
impl<J:InteractiveJob> OriginalWorkerJobAdmission<J>{
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{
  if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}self.validate(cx)?;if !Self::enter(cx,0,0,true){return Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}
  if !self.closing{self.closing=true;Self::metadata(cx)?;return Ok(InteractiveJobCloseStep::Pending{progress:RetainedCloneProgress{copied_items:1,..Default::default()}})}
  if let Some(owner)=self.authority.as_mut(){if !owner.terminal_is_empty(){if owner.has_original_cancel_alias_witness(cx.original_cancel_token()){let turn=cx.with_original_effect(cx.retained_grant(),|cx,effect|owner.return_original_cancel_alias_step(cx.original_cancel_token(),effect))?.map_or(semio_framework_value::RetainedWorkOutcome{result:Ok(None),work:0},|(turn,_)|turn);let blocked=matches!(&turn.result,Err(semio_framework_async::CancelTokenRetirementError::Blocked(_)));let result=match turn.result{Ok(Some(step))=>Ok(step),Ok(None)|Err(semio_framework_async::CancelTokenRetirementError::Blocked(_))=>Ok(RetainedCloneStep::Progress(Default::default())),Err(semio_framework_async::CancelTokenRetirementError::Refused(error))=>Err(error)};let step=receive_original_retained_work(cx,RetainedWorkOutcome{result,work:turn.work})?;return Ok(if blocked{InteractiveJobCloseStep::Blocked}else{InteractiveJobCloseStep::Pending{progress:step.progress()}})}return match owner.close_step(cx)?{WorkerJobCloseStep::Pending{progress}=>Ok(InteractiveJobCloseStep::Pending{progress}),WorkerJobCloseStep::Blocked=>Ok(InteractiveJobCloseStep::Blocked),WorkerJobCloseStep::Complete{progress}=>Ok(InteractiveJobCloseStep::Pending{progress})}}self.authority.take();Self::metadata(cx)?;return Ok(InteractiveJobCloseStep::Pending{progress:RetainedCloneProgress{copied_items:1,..Default::default()}})}
  if self.storage.capacity()>0{let bytes=self.storage.capacity()*size_of::<NativeWorkerAuthorityState<J>>();if !Self::enter(cx,0,bytes,true){return Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}drop(std::mem::take(&mut self.storage));let progress=RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()};receive_original_retained_work(cx,RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Progress(progress)),work:1})?;return Ok(InteractiveJobCloseStep::Pending{progress})}
  if !self.prepared.terminal_is_empty(){return self.prepared.close_step(cx)}
  self.binding=None;self.closing=false;Self::metadata(cx)?;Ok(InteractiveJobCloseStep::Complete{progress:RetainedCloneProgress{copied_items:1,..Default::default()}})
 }
}
impl<J> Drop for OriginalWorkerJobAdmission<J>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"worker admission reached Drop before its genuine paid close")}}
